#!/bin/zsh
TMUX=/opt/homebrew/bin/tmux
[ -x "$TMUX" ] || TMUX=/usr/local/bin/tmux
send() { $TMUX send-keys -t $1 C-u; sleep 1; $TMUX send-keys -t $1 "$2"; sleep 2; $TMUX send-keys -t $1 Enter; sleep 2; $TMUX send-keys -t $1 Enter; sleep 1; echo "sent -> $1"; }
MSG="RULING 3 from V supersedes the no-proxies rule - read it at the end of /Users/vinaybhardwaj/dev/_fable/orders/RULING-durable-centroids.md. V's words: I want all possible ways of matching doctors voices, any proxy you can use. Roster, room slugs, room bindings, the September schedule, phone login, PIN attestation, Jev role signals, transcript self-identification, voice recurrence and V's ear are all allowed. The engineering rule that keeps it safe: proxies propose, voice disposes - every proxy is a recorded signal, never a label alone; a segment is attributed to a doctor only when at least two independent signals agree and the voice is consistent with that doctor's other audio; disagreement is held out; every attribution records which signals produced it so a bad signal can be withdrawn and centroids rebuilt."
send lx:1.1 "$MSG For your survey this widens question 5 into an inventory: for EVERY signal in that list, report whether it exists in our data today, its coverage in rooms and phone sessions, and whether it is independent of the others or secretly derived from one of them - two signals that share a source are not two votes. Two of them I already know are empty: room_day.doctor_id is NULL in all 106 room-days and room_clinician_attestation has 0 rows."
send split-speaker:1.1 "$MSG For you: the roster is back as a legitimate signal, not only a search hint. Keep going with the Jev trial as ordered."
send scribe:1.1 "$MSG No change to your speech-gate build - that sits underneath every signal, because a proxy attached to a noise segment is still noise. Carry on."
